251	     *
252	     * 供 AutoTemplateActionContext 经 `this.scope.getData()` 使用：action 无论挂在 x-data 元素本身
253	     * 还是其后代，均可拿到"当前所在 x-data 块"的可读可写响应式代理——区别于 `getContext`
254	     * 返回的只读聚合视图（写已有键会抛 TypeError）。整条链均无 x-data 时返回 null。
255	     *
256	     * data 引用恒定（DataDirective 铁律：永不整体替换 `_scopes[id]`），无需缓存；
257	     * 每次调用沿链 O(深度) 查找，开销可忽略。
258	     */
259	    getData(): Record<string, any> | null {
260	        let s: AutoTemplateScope | null = this;
261	        while (s) {
262	            if (s.data) return s.data;
263	            s = s.parent;
264	        }
265	        return null;
266	    }
267	
268	    /**
269	     * 沿 parent 链就近查找命名模板块，到顶兜底全局块（ADR-0021 决策 5/9）。
270	     *
271	     * 消费者协议的核心查找：从本 scope 起，向上取首个含该名 block 的祖先 scope，
272	     * 命中即止（就近覆盖语义——内层 scope 的同名块遮蔽外层、亦遮蔽全局）。scope 链无命中时
273	     * 兜底查 `engine.options.blocks`（全局块，字符串入参，懒预编译缓存），由 `engine.getBlock`
274	     * 解析/包装/缓存。整条链（含全局）无命中返回 undefined，由消费者回退其默认块（块兜底）。
275	     *
