/**
 * 组件定义（ADR-0022 决策二-1、决策七）。
 *
 * compiler 前置 transformer 命中 x-component 元素时，提取其 `<script setup>` / `<style>` 子节点、
 * 求值合并 setup、深克隆剩余 DOM 为冻结快照，组装成本对象。存入 `scope.components[name]` 或
 * 嵌套场景下父组件的 `def.components`（定义 scope 链）。
 *
 * `getComponent(name)` 返回的 HTMLElement 快照（向后兼容 x-loading 等消费者）仍挂在 scope.components；
 * ComponentDef 的额外元数据（setup/hooks/styles/parent/components）经 engine 的 `defScopeMap`
 * 以快照根元素为 key 反查。这样既保持 getComponent 的 HTMLElement 契约不变，又让 x-use 能取到组件元数据。
 */
export interface ComponentDef {
    /** 组件名（无值 x-component 取 "default"） */
    name: string;
    /** 冻结快照根元素（深克隆、保留指令属性、**已移除** `<script setup>`/`<style>` 子节点、未编译） */
    snapshot: HTMLElement;
    /** 合并后的 setup（data 方法、methods、四阶段钩子）；无 `<script setup>` 时为 undefined */
    setup: ComponentSetup | undefined;
    /** 合并后的钩子表（从 setup 提取，实例化时克隆到 scope.hooks）；无钩子时为 undefined */
    hooks: ComponentHooks | undefined;
    /** 合并后的组件作用域 CSS 文本数组（每个 `<style>` 一项）；无 `<style>` 时为 undefined */
    styles: string[] | undefined;
    /**
     * 父组件定义（定义 scope 链，ADR-0022 决策七-3）。
     * 嵌套声明时指向声明它的外层组件 def；顶层组件（直接归属运行期 scope）为 null。
     */
    parent: ComponentDef | null;
    /**
     * 私有子组件表（嵌套声明，ADR-0022 决策七-2）。
     * 仅对本组件实例可见（严格私有，决策 U5=A）；key=组件名，value=子 ComponentDef。
     */
    components: Record<string, ComponentDef> | null;
}

