import type { ComponentDef, ComponentSetup, ComponentHooks } from "../directives/component-def";
import { evalComponentSetup, mergeComponentSetups, extractComponentHooks } from "./setup";

/**
 * 从组件元素（含 `<script setup>`/`<style>` 子节点）提取并组装组件定义（ADR-0022 决策二/四）。
 *
 * 核心步骤：
 * 1. 遍历子节点，收集所有 `<script setup>`（type=setup 或无 type 且匹配 setup 形态）与 `<style>`；
 * 2. 深克隆元素为冻结快照，并从快照中**移除**这些 `<script setup>`/`<style>` 节点（不进实例化 DOM）；
 * 3. 求值各 `<script setup>`（new Function，信任代码，失败 warn 丢弃）；
 * 4. 合并 setups（data 收集、methods 浅合并、同名 hooks 串行，决策四-1/R3=A）；
 * 5. 组装 ComponentDef（snapshot/setup/hooks/styles）。
 *
 * parent/components（定义 scope 链）由调用方在归属判定后填充，本函数只产出 def 主体。
 *
 * @param componentEl 原树中的 x-component 元素（读取子节点结构）
 * @param name        组件名
 * @param warn        warn 日志函数
 * @returns 组件定义（snapshot 已剥离 script/style 子节点）
 */
export function buildComponentDef(
    componentEl: HTMLElement,
    name: string,
    warn: (msg: string) => void,
): ComponentDef {
    // 1+2. 收集 script setup / style 的 DOM 引用，并标记待从快照移除
    const setupScripts: HTMLScriptElement[] = [];
    const styleEls: HTMLStyleElement[] = [];
    for (const child of Array.from(componentEl.children)) {
        if (child instanceof HTMLScriptElement && child.type === "setup") {
            setupScripts.push(child);
        } else if (child instanceof HTMLStyleElement) {
            styleEls.push(child);
        }
    }

    // 2. 深克隆快照，并移除 script setup / style（按元素身份匹配——克隆后身份改变，改用位置/内容匹配）
    const snapshot = componentEl.cloneNode(true) as HTMLElement;
    // 从快照中移除对应的 script[type=setup] 与 style（重新查询，因克隆后引用已变）
    snapshot.querySelectorAll("script[type='setup'], script[type=setup]").forEach((n) => n.remove());
    // style：移除所有直接子 style（组件作用域样式专指组件直接声明的 style）
    const snapStyles: HTMLStyleElement[] = [];
    for (const child of Array.from(snapshot.children)) {
        if (child instanceof HTMLStyleElement) snapStyles.push(child);
    }

    // 3. 求值各 script setup
    const setups = [];
    for (const s of setupScripts) {
        const text = s.textContent?.trim() ?? "";
        const parsed = evalComponentSetup(text, name, warn);
        if (parsed) setups.push(parsed);
    }
    // 4. 合并
    const setup: ComponentSetup | undefined = mergeComponentSetups(setups);
    const hooks: ComponentHooks | undefined = extractComponentHooks(setup);

    // 5. 收集 style 文本
    const styles = styleEls.length > 0 ? styleEls.map((s) => s.textContent ?? "") : undefined;

    // 同步移除快照里的 style 节点（实例化 DOM 不含样式元素，样式经 scoped CSS 注入 head）
    snapStyles.forEach((s) => s.remove());

    return {
        name,
        snapshot,
        setup,
        hooks,
        styles,
        parent: null,
        components: null,
    };
}

