559	        // 的 appendChild 会导致子节点重复。
560	        if (reuseEl) {
561	            while (el.firstChild) el.removeChild(el.firstChild);
562	        }
563	        const scope = new AutoTemplateScope(this.engine, el, itemTemplate);
564	        scope.localData = localData;
