 * @param info     原始指令信息（来自 getDirectives）；value/attr/modifiers/options 同时提取为便捷字段
 */
constructor(
    engine: AutoTemplateEngine,
    binding: AutoTemplateScope | undefined,
    info: AutoDirectiveInfo,
) {
    this.engine = engine;
