        this.instanceDef = def ?? null;
        // 属性继承（T4=B）：宿主化身组件根前，把宿主属性并入组件快照根的克隆
        const host = this.el;
        // compileChild 用 reuseEl=host：复用宿主节点身份，清空原内容，编译组件快照子树挂入。
        // 属性继承在 compileChild 后做（此时 host 已是组件根，含组件快照根的属性）。
        const result = this.engine.compiler.compileChild(
            snapshot,
            this.binding,
            {},
            host,
            props,
            def,
        );
