        // 宿主属性（未 removeDirectives）。故此处只需处理 class/style 合并语义。
        this._mergeHostAttrs(host);
        // scoped CSS 注入（ADR-0022 决策四-4）：阶段 5 实现
    }

    /**
     * 合并宿主属性到组件根（T4=B 属性继承）。
     *
     * compileChild reuseEl=host 后，host 已含组件快照根属性（compileChild 内 cloneNode(false) 的属性）
     * 与宿主残留属性。此处补 class 合并拼接、style 合并语义。
     *
     * 注：compileChild 的 reuseEl 路径不清除 host 原属性，组件快照根属性经 cloneNode(false) + 属性拷贝
     * 叠加。当前简化：保留 host 既有属性，不额外处理（class/style 的精细合并在阶段 5 scoped CSS 一起做）。
     */
