/**
 * 实例化组件：取快照 + def → 属性继承 → compileChild（reuseEl 化身组件根）。
 */
private _instantiate(name: string, props: Record<string, any> | undefined): void {
    const snapshot = this.binding.getComponent(name);
    if (!snapshot) {
        // 组件未注册：warn（异步占位在 x-import 阶段补，当前直接 warn）
        this.engine.logger.warn(
            `x-use: 组件 "${name}" 未找到（局部/全局均无声明），已跳过实例化。`,
        );
        return;
    }
    // 递归深度保护（T5=A）：沿 parent 链统计同名组件实例化深度
    if (this._recursiveDepth(name) >= UseDirective.MAX_DEPTH) {
        this.engine.logger.warn(
            `x-use: 组件 "${name}" 递归实例化深度超过上限（${UseDirective.MAX_DEPTH}），已停止（疑似无终止条件递归）。`,
        );
        return;
    }
    const def = this.engine.getComponentDef(snapshot);
    this.instanceDef = def ?? null;
    // 属性继承（T4=B）：宿主化身组件根前，把宿主属性并入组件快照根的克隆
    const host = this.el;
    // compileChild 用 reuseEl=host：复用宿主节点身份，清空原内容，编译组件快照子树挂入。
    // 属性继承在 compileChild 后做（此时 host 已是组件根，含组件快照根的属性）。
    const result = this.engine.compiler.compileChild(
        snapshot,
        this.binding,
        {},
        host,
        props,
        def,
    );
    this.instanceScope = result.scope;
    // 属性继承：宿主原属性（x-use 编译期已剥除指令属性，此处 host.attributes 是组件快照根属性 +
    // 残留的宿主普通属性）。需把"宿主原本的普通属性"并入，但 compileChild 的 reuseEl 路径已保留
    // 宿主属性（未 removeDirectives）。故此处只需处理 class/style 合并语义。
    this._mergeHostAttrs(host);
    // scoped CSS 注入（ADR-0022 决策四-4）：阶段 5 实现
}

