/**
 * 找匹配的闭合 `}`（从开 `{` 起，考虑嵌套）。
 */
function findMatchingBrace(css: string, openIdx: number): number {
    let depth = 0;
    for (let i = openIdx; i < css.length; i++) {
        if (css[i] === "{") depth++;
        else if (css[i] === "}") {
            depth--;
            if (depth === 0) return i;
        }
    }
