 * 给元素及其后代打 scoped 属性 `data-cmp-{scopeId}`（实例化时调用）。
 */
export function mountComponentScopedAttr(root: HTMLElement, scopeId: number): void {
    root.setAttribute(`data-cmp-${scopeId}`, "");
