20	    on(event: string, listener: (...args: any[]) => void): this {
21	        if (!this.listeners.has(event)) this.listeners.set(event, new Set());
22	        this.listeners.get(event)!.add(listener);
23	        return this;
24	    }
25	    off(event: string, listener: (...args: any[]) => void): this {
26	        this.listeners.get(event)?.delete(listener);
