override created() {
    const urlExpr = this.value == null ? "" : String(this.value).trim();
    if (urlExpr === "") {
        this.engine.logger.warn(`x-import: 缺少 url，已跳过。`);
        return;
    }
    // url 经 scope.watch 求值（响应式，支持路径/表达式/x-data 局部）；初值立即加载，变化重载
    const initialUrl = this.binding.watch(this.value, ({ value: url }) => {
        this._load(url);
    });
    this._load(initialUrl);
}

