    // - 含表达式特征（空白、花括号、状态变量等）→ watch 求值得 url（响应式）。
    if (isLiteralUrl(raw)) {
        this._load(raw);
        return;
    }
    // 表达式：watch 求值得 url（响应式，url 变化重载）
    const initialUrl = this.binding.watch(this.value, ({ value: url }) => {
        this._load(url);
    });
    this._load(initialUrl);
}

