47	export function buildAction<A extends (...args: any[]) => any>(
48	    emit: ActionEmit,
49	    name: string,
50	    action: A,
51	    local = false,
52	): A {
53	    if ((action as any).__buildActionWrapped) return action;
54	    const wrapped = function (this: unknown, ...args: Parameters<A>) {
55	        // 触发元素：仅 AutoTemplateActionContext（经 x-on 触发）有 el；命令式直调无 el
56	        const triggerEl = (this as any)?.el as HTMLElement | undefined;
57	        // 双通道广播：总线（全局通配，仅全局 action）+ DOM 冒泡（祖先聚合，全局+局部）。
58	        // local=true（局部 action）：跳过 emit，只 DOM——避免同名局部 action 总线串扰（ADR-0012）。
59	        // triggerEl 为空（命令式直调）：跳过 DOM；全局 action 仍 emit 总线，局部 action 静默。
60	        const broadcast = (phase: string, extra: Record<string, any> = {}) => {
61	            if (!local) emit(`actions/${name}/${phase}`, { name, ...extra });
62	            if (triggerEl) {
63	                triggerEl.dispatchEvent(
64	                    new CustomEvent(`action:${name}`, {
65	                        bubbles: true,
66	                        composed: true,
67	                        detail: { name, phase, ...extra },
68	                    }),
69	                );
70	            }
71	        };
72	        // pending 在 apply 前（开始执行）；同步/异步统一
73	        broadcast("pending");
