75	        try {
76	            result = action.apply(this, args);
77	        } catch (error) {
78	            // 同步抛错：广播 rejected 后 rethrow（保持错误传播：x-on eval.ts catch / 命令式调用者）
79	            broadcast("rejected", { error });
