75	        try {
76	            result = action.apply(this, args);
77	        } catch (error) {
78	            // 同步抛错：广播 rejected 后 rethrow（保持错误传播：x-on eval.ts catch / 命令式调用者）
79	            broadcast("rejected", { error });
80	            throw error;
81	        }
82	        // 成功完成：同步立即 resolved；异步（thenable）等 then
83	        if (result && typeof (result as any).then === "function") {
84	            (result as Promise<any>).then(
85	                (value) => broadcast("resolved", { result: value }),
86	                (error) => broadcast("rejected", { error }),
87	            );
88	        } else {
89	            broadcast("resolved", { result });
90	        }
91	        return result;
92	    } as A;
93	    (wrapped as any).__buildActionWrapped = true;
94	    return wrapped;
95	}
