1	/**
2	 * 组件作用域 CSS 改写器（ADR-0022 决策四-4，属性后缀法，仿 Vue `<style scoped>`）。
3	 *
4	 * 给定组件 CSS 文本与作用域 id，把每条选择器末尾追加 `[data-cmp-{id}]`，使样式仅命中本组件实例
5	 * 的元素（组件根 + 后代在实例化时被打 `data-cmp-{id}` 属性）。不支持穿透（无 `:deep()`/`>>>`），
6	 * 纯隔离——YAGNI，真实需求出现再加（仅改写器一个额外规则，不影响架构）。
7	 *
8	 * 改写规则（仿 Vue 行为）：
9	 * - `.foo` → `.foo[data-cmp-1]`（末尾选择器加后缀）
10	 * - `.a .b` → `.a .b[data-cmp-1]`（仅末尾选择器加，祖先选择器不加）
11	 * - `a, b` → `a[data-cmp-1], b[data-cmp-1]`（逗号分组，各组末尾分别加）
12	 * - `:hover` → `[data-cmp-1]:hover`（伪类：属性后缀置于伪类**前**，Vue 行为）
13	 * - `::before` → `[data-cmp-1]::before`（伪元素同伪类）
14	 * - `@media (...) { .foo {} }` → 包裹保留，内部 `.foo` 照常改写
15	 * - `@keyframes name { ... }` → 整体保留不改写（关键帧名不隔离，按组件名约定避免冲突）
16	 *
17	 * @param cssText  组件 `<style>` 原始 CSS 文本
18	 * @param scopeId  作用域 id（数值，用作 `data-cmp-{scopeId}` 属性名后缀）
19	 * @returns 改写后的 CSS 文本
20	 */
21	export function rewriteScopedCss(cssText: string, scopeId: number): string {
22	    const attr = `[data-cmp-${scopeId}]`;
23	    // 按顶层规则块改写：用状态机遍历，区分普通规则、@-rule（@media/@keyframes/@supports 等）。
24	    // 简化策略：按 `{` `}` 深度跟踪，对每个「选择器 { 体 }」单元改写其选择器部分。
25	    return rewriteStylesheet(cssText, attr);
