28	/**
29	 * 改写整个样式表：遍历顶层规则，对普通规则改写选择器，对 @-rule 递归处理其内部。
30	 */
31	function rewriteStylesheet(css: string, attr: string): string {
32	    let out = "";
33	    let i = 0;
34	    while (i < css.length) {
35	        // 跳过空白
36	        while (i < css.length && /\s/.test(css[i]!)) {
37	            out += css[i];
38	            i++;
39	        }
40	        if (i >= css.length) break;
41	        // 注释保留
42	        if (css.startsWith("/*", i)) {
43	            const end = css.indexOf("*/", i + 2);
44	            const stop = end === -1 ? css.length : end + 2;
45	            out += css.slice(i, stop);
46	            i = stop;
47	            continue;
48	        }
49	        // @-rule
50	        if (css[i] === "@") {
51	            const rule = readAtRule(css, i);
52	            out += rewriteAtRule(rule.prelude, rule.body, attr);
53	            i = rule.end;
54	            continue;
55	        }
56	        // 普通规则：选择器 { 体 }
57	        const braceIdx = css.indexOf("{", i);
58	        if (braceIdx === -1) {
59	            // 残余文本（无体的 at-rule 如 @import，或语法残缺），原样保留
60	            out += css.slice(i);
61	            break;
62	        }
63	        const selector = css.slice(i, braceIdx);
64	        const bodyEnd = findMatchingBrace(css, braceIdx);
65	        const body = css.slice(braceIdx, bodyEnd + 1);
66	        out += `${rewriteSelectorList(selector, attr)}${body}`;
67	        i = bodyEnd + 1;
