75	 */
76	function readAtRule(css: string, start: number): { prelude: string; body: string; end: number } {
77	    const braceIdx = css.indexOf("{", start);
78	    // 无 body 的 at-rule（@import ...;）
79	    const semiIdx = css.indexOf(";", start);
80	    if (semiIdx !== -1 && (braceIdx === -1 || semiIdx < braceIdx)) {
81	        return { prelude: css.slice(start, semiIdx + 1), body: "", end: semiIdx + 1 };
82	    }
83	    const prelude = css.slice(start, braceIdx);
84	    const bodyEnd = findMatchingBrace(css, braceIdx);
85	    return {
86	        prelude,
87	        body: css.slice(braceIdx, bodyEnd + 1),
88	        end: bodyEnd + 1,
