122	/**
123	 * 按顶层逗号分割（忽略括号内的逗号）。
124	 */
125	function splitTopLevelCommas(text: string): string[] {
126	    const parts: string[] = [];
127	    let depth = 0;
128	    let cur = "";
129	    for (const ch of text) {
130	        if (ch === "(") depth++;
131	        if (ch === ")") depth = Math.max(0, depth - 1);
132	        if (ch === "," && depth === 0) {
133	            parts.push(cur);
134	            cur = "";
135	        } else {
136	            cur += ch;
137	        }
138	    }
139	    if (cur.trim()) parts.push(cur);
140	    return parts;
