16	 * 从组件元素（含 `<script setup>`/`<style>` 子节点）提取并组装组件定义（ADR-0022 决策二/四）。
17	 *
18	 * 核心步骤：
19	 * 1. 在原树收集所有 `<script setup>` 的文本内容与 `<style>` 的文本内容（克隆前读，引用稳定）；
20	 * 2. 深克隆元素为冻结快照，并在快照上**移除**这些 `<script setup>`/`<style>` 子节点（不进实例化 DOM）；
21	 * 3. 求值各 `<script setup>`（new Function，信任代码，失败 warn 丢弃，决策四-2/3）；
22	 * 4. 合并 setups（data 收集、methods 浅合并、同名 hooks 串行，决策四-1/R3=A）；
23	 * 5. 组装 ComponentDef（snapshot/setup/hooks/styles）。
24	 *
25	 * @param componentEl 原树中的 x-component 元素（读取子节点结构）
26	 * @param name        组件名
27	 * @param warn        warn 日志函数
28	 * @returns 组件定义（snapshot 已剥离 script/style 子节点）
29	 */
30	export function buildComponentDef(
31	    componentEl: HTMLElement,
32	    name: string,
33	    warn: (msg: string) => void,
34	): ComponentDef {
35	    // 1. 原树收集 setup 文本与 style 文本（克隆前读，避免克隆后引用错位）
36	    const setupTexts: string[] = [];
37	    const styleTexts: string[] = [];
38	    let hasSetupOrStyle = false;
39	    for (const child of Array.from(componentEl.children)) {
40	        if (child instanceof HTMLScriptElement && isSetupScript(child)) {
41	            setupTexts.push(child.textContent?.trim() ?? "");
42	            hasSetupOrStyle = true;
43	        } else if (child instanceof HTMLStyleElement) {
44	            styleTexts.push(child.textContent ?? "");
45	            hasSetupOrStyle = true;
46	        }
47	    }
48	
49	    // 2. 深克隆快照，移除 script setup / style（克隆后在快照上重新遍历，按相同判定移除）
50	    const snapshot = componentEl.cloneNode(true) as HTMLElement;
51	    if (hasSetupOrStyle) {
52	        for (const child of Array.from(snapshot.children)) {
53	            if (
54	                (child instanceof HTMLScriptElement && isSetupScript(child)) ||
55	                child instanceof HTMLStyleElement
56	            ) {
57	                child.remove();
58	            }
59	        }
60	    }
61	
62	    // 3. 求值各 script setup
63	    const setups = [];
64	    for (const text of setupTexts) {
65	        const parsed = evalComponentSetup(text, name, warn);
66	        if (parsed) setups.push(parsed);
67	    }
68	    // 4. 合并
69	    const setup: ComponentSetup | undefined = mergeComponentSetups(setups);
70	    const hooks: ComponentHooks | undefined = extractComponentHooks(setup);
71	
72	    // 5. style 文本（空数组收敛为 undefined）
73	    const styles = styleTexts.length > 0 ? styleTexts : undefined;
74	
75	    return {
76	        name,
77	        snapshot,
78	        setup,
79	        hooks,
80	        styles,
81	    };
82	}
