### 3. scope 新增 `getMethodThis()`(懒构造 Proxy)

```ts
/** 构造 method 调用时的 Proxy this(懒构造、缓存)。 */
getMethodThis(): any {
    if (this._methodThis) return this._methodThis;
    const scope = this;
    this._methodThis = new Proxy(scope, {
        get(_t, k: string | symbol) {
            // 1) 框架引用(按你确认的规则)
            if (k === "data") return scope.getContext();
            if (k === "state") return scope.engine.state;
            // 若规则 B: engine/scope 直接 Reflect.get；若规则 A/C: $engine/$scope
            // 2) method 优先(组件边界内):本 scope 及祖先组件 scope 的 methods
            const m = scope.getMethod(String(k));
            if (typeof m === "function") return m.bind(proxy);
            // 3) scope 原生(getAction/watch/getComponent/...):从真实 scope 取,bind scope
            const native = Reflect.get(scope, k);
            return typeof native === "function" ? native.bind(scope) : native;
        },
        has() { return true; },  // 让 with(this){...} 与存在性检查一致
        set(_t, k, val) {
            // 写入透传:框架引用键禁止覆盖,其余写聚合视图或 scope
            ...
        },
    });
    return this._methodThis;
}
```

