/**
 * 串行执行某阶段的组件生命周期钩子（ADR-0022 决策三）。
 *
 * 每个 hook 用 ComponentMethodContext 作 this（复用 ActionContext 形态：data=getContext 视图、
 * state=engine.state、scope、el）。单个 hook 抛错 try-catch 记 error 不阻断后续 hook（容错）。
 * hooks 为 null（非组件 scope）或该阶段无 hook 时静默无副作用。
 */
private _runHooks(phase: "created" | "mounted" | "beforeUnmount" | "unmounted"): void {
    const fns = this.hooks?.[phase];
    if (!fns || fns.length === 0) return;
    const ctx = {
        el: this.el!,
        data: this.getContext(),
        scope: this,
        state: this.engine.state,
        store: this.engine.store,
        engine: this.engine,
    };
    for (const fn of fns) {
        try {
            fn.call(ctx);
        } catch (e: any) {
            this.engine.logger.error(
                `x-component hook "${phase}" 执行失败: ${e?.message ?? e}`,
            );
        }
    }
}

