1	import { describe, expect, test, beforeEach, afterEach } from "bun:test";
2	import "./setup";
3	import { mount, nextTick } from "./helpers";
4	import type { ComponentDef } from "../directives/component-def";
5	import { rewriteScopedCss, injectComponentStyle, releaseComponentStyle } from "../utils/scopedStyle";
6	import { exprToVarName, extractStyleBinds } from "../utils/styleBind";
7	
8	/**
9	 * x-scope（结构占位）+ x-component（命名模板组件供体）+ 全局组件测试。
10	 *
11	 * 覆盖 ADR-0021 全部决策（含决策 7 修订、9 全局组件、10 自动包装、11 懒预编译）：
12	 * - Q2 x-scope 注册占位类建 scope
13	 * - Q3 组件归属任意深度（跨中间纯 div）
14	 * - Q4 冗余 x-scope 静默
15	 * - Q6 组件存深克隆副本
16	 * - Q7 编译期摘除（不进结果 DOM、不建 scope）+ 组件根不注入 x-scope（决策 7 修订）
17	 * - Q8 同元素指令随组件冻结
18	 * - Q9 default 唯一性（直接归属）+ 自由命名
19	 * - 决策 9 getComponent 沿 parent 链就近 + 全局组件兜底 + 局部遮蔽全局
20	 * - 决策 10 全局组件自动包装（单根打标/多根包 div/已含尊重/纯文本）
21	 * - 决策 11 懒预编译缓存（首次解析、后续 deepClone、失败视为未命中）
22	 * - x-loading 消费 loading 组件替换默认组件（data 注入）
23	 */
24	
25	describe("x-scope 结构占位", () => {
26	    test("Q2：纯容器声明 x-scope 即建 scope（后代 x-component 有归属）", () => {
27	        // x-scope 让无指令的 div 建 scope，使内部 x-component 能归属、被摘除
28	        const { root } = mount(`<div x-scope><div x-component="loading">L</div></div>`, {});
29	        // x-component 被摘除（不进结果 DOM），x-scope 属性也被剥除
30	        expect(root.querySelector("[x-component]")).toBeNull();
31	        expect(root.querySelector("[x-scope]")).toBeNull();
32	        // x-scope 容器本身保留（仅属性被剥）
33	        expect(root.querySelector("div")).not.toBeNull();
34	    });
35	
36	    test("Q2：无 x-scope 时纯容器不建 scope（对照）", () => {
37	        // 纯 div 无指令无插值 → 不建 scope → 内部无 x-component 时原样渲染子树
38	        const { root } = mount(`<div><span>keep</span></div>`, {});
39	        expect(root.querySelector("span")?.textContent).toBe("keep");
40	    });
41	
